/**
 * Wire and domain types for the LLM-assisted executive narrative.
 *
 * The narrative is generated by the meriv2-orchestrator (the only service that
 * holds model credentials) from an evidence packet that api-strategy builds
 * from an already audience-filtered report snapshot. api-strategy treats the
 * returned envelope as untrusted wire data and re-verifies every paragraph
 * before a renderer may use it; anything that fails falls back to the
 * deterministic, fact-listing rendering that shipped before this feature.
 */

export const REPORT_NARRATIVE_SECTION_IDS = [
  "executive_summary",
  "situation",
  "objectives_and_ask",
  "stakeholders",
  "constraints_and_timing",
  "decisions_and_risks",
  "roadmap_outlook",
] as const;

export type ReportNarrativeSectionId =
  (typeof REPORT_NARRATIVE_SECTION_IDS)[number];

/** Verbatim source text the model may cite. Ids are opaque to the model. */
export interface ReportNarrativeEvidence {
  id: string;
  text: string;
  /** Human label shown in "Sources" lines; never sent to the model as prose. */
  sourceTitle: string;
}

export interface ReportNarrativeParagraph {
  text: string;
  evidenceIds: string[];
}

export interface ReportNarrativeSection {
  id: ReportNarrativeSectionId;
  paragraphs: ReportNarrativeParagraph[];
}

/** Envelope returned by the orchestrator. Untrusted until verified. */
export interface ReportNarrativeEnvelope {
  sections: ReportNarrativeSection[];
  model: string;
  generatedAt: string;
  usage: { inputTokens: number; outputTokens: number };
  attempts: number;
  /** Paragraphs the orchestrator's own citation gate already removed. */
  droppedParagraphs: number;
  usedFallback: boolean;
}

export type ReportNarrativeRejectionReason =
  | "unknown_section"
  | "empty_text"
  | "too_long"
  | "too_many_paragraphs"
  | "no_evidence_cited"
  | "unknown_evidence_id"
  | "leaked_marker"
  | "ungrounded_number"
  | "ungrounded_date"
  | "ungrounded_name";

export interface ReportNarrativeRejection {
  sectionId: string;
  reason: ReportNarrativeRejectionReason;
  /** The offending token when the reason is an ungrounded value. */
  detail: string | null;
  /** Clipped paragraph text for logs and the internal appendix. */
  excerpt: string;
}

/** A verified paragraph carries the human-readable titles of what it cites. */
export interface VerifiedNarrativeParagraph extends ReportNarrativeParagraph {
  sourceTitles: string[];
}

export interface VerifiedNarrativeSection {
  id: ReportNarrativeSectionId;
  paragraphs: VerifiedNarrativeParagraph[];
}

export interface VerifiedReportNarrative {
  sections: VerifiedNarrativeSection[];
  model: string;
  generatedAt: string;
  usage: { inputTokens: number; outputTokens: number };
  attempts: number;
  acceptedParagraphs: number;
  rejectedParagraphs: number;
  /** Paragraphs the orchestrator's own gate dropped before we saw them. */
  orchestratorDroppedParagraphs: number;
  rejections: ReportNarrativeRejection[];
}

export function narrativeSection(
  narrative: VerifiedReportNarrative | null | undefined,
  id: ReportNarrativeSectionId,
): VerifiedNarrativeParagraph[] {
  if (!narrative) return [];
  return (
    narrative.sections.find((section) => section.id === id)?.paragraphs ?? []
  );
}
